const roots=['tests/current-atlas-title-tour-delivery.test.mjs','tests/title-tour-functional-delivery.test.mjs','tests/regional-tour-entry-delivery.test.mjs'];
function verify(){assert.equal(hash(file),expected);for(const r of source.sourceRows)assert.equal(hash(source.website+'/'+r.path),r.sha256,r.path);for(const d of source.dependencies){assert.equal(hash(d.file),d.sha256);assert.equal(hash(d.entry),d.entrySha256);}assert.equal(json('CURRENT_CHECKPOINT.json').activeWork.current.ownerPreviewPolicy.restartPermitted,false);}
verify();const index=json('CURRENT_CHECKPOINT.json');assert.deepEqual(index.activeWork.current.activeExecutionSessions,[]);index.activeWork.current.activeExecutionSessions=[{kind:'title-tour-website-focused',driverPid:process.pid,evidence:dir,sourceSha256:expected}];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(index,null,2)+'\n');
try{global.gc();const run=await guarded({site:source.website,dir,command:'--max-old-space-size=1024 --test --test-concurrency=1 '+roots.join(' '),heap:1024,aggregate:2048,minimum:4096,extraEnv:{VM_ATLAS_SOURCE_REPO:source.atlas,ATLAS_SOURCE_REPO:source.atlas,VM_CURRENT_SOURCE_RECEIPT:file,VM_CURRENT_SOURCE_SHA256:expected}});verify();const text=fs.readFileSync(dir+'/runner.stdout.log','utf8'),counts=Object.fromEntries(['tests','pass','fail','skipped','cancelled','todo'].map(k=>{const matches=[...text.matchAll(new RegExp('^# '+k+' (\\d+)$','gm'))];return[k,matches.length?Number(matches.at(-1)[1]):null];}));const passing=run.passing&&counts.tests>30&&counts.fail===0&&counts.skipped===0;const result={at:new Date().toISOString(),passing,run,roots,counts,source:{path:file,sha256:expected},historicalRootsAndSourceContextsPreserved:true,wholeStockSuitePassing:false,sourceAndAllDependenciesUnchanged:true,installed:false,ownerPreviewChanged:false,clinicalApproval:false,patientSpaceRegistration:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({result:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),passing,counts}));process.exitCode=passing?0:1;}finally{const i=json('CURRENT_CHECKPOINT.json');i.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(i,null,2)+'\n');}
